
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.957694345788876e+00, -1.920696839201657e+00, -1.868868950325468e+00, -1.797106638301197e+00, -1.699394135630184e+00, -1.569514485945391e+00, -1.402741902454917e+00, -1.198913332528047e+00, -9.665046019367107e-01, -7.238306207589783e-01, -4.893791239589972e-01, -3.498526253604957e-01, -3.108361796474304e-01, -2.523288291537429e-01, -1.787867556485390e-01, -1.105120450656406e-01, -5.887794562975593e-02, -2.179119375759838e-02, -4.757249891922843e-03, -5.351289455452314e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


